require __DIR__.'/app-bootstrap.php';$u=require_admin();require $privateRootPath.'/src/admin_users_layout.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$name=trim((string)($_POST['display_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$isArtist=isset($_POST['is_artist']);$paypal=trim((string)($_POST['paypal_email']??''));$artistNames=array_values(array_unique(array_filter(array_map(static fn(string $value):string=>trim($value),preg_split('/[\r\n]+/',(string)($_POST['artist_names']??''))?:[]),static fn(string $value):bool=>$value!=='')));if($name===''||mb_strlen($name)>120)throw new RuntimeException('Enter a display name.');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');$existingUser=$pdo->prepare('SELECT id,banned_at FROM users WHERE email=? LIMIT 1');$existingUser->execute([$email]);$existingUser=$existingUser->fetch();if($existingUser)throw new RuntimeException($existingUser['banned_at']?'This email address is permanently banned.':'That email address is already registered.');if($isArtist&&$paypal!==''&&!filter_var($paypal,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid PayPal email address or leave it blank.');if(count($artistNames)>10)throw new RuntimeException('Enter no more than 10 artist names.');$verified=isset($_POST['email_verified'])?date('Y-m-d H:i:s'):null;$pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO users(email,password_hash,display_name,email_verified_at,is_artist,paypal_email,paypal_email_updated_at) VALUES(?,?,?,?,?,?,?)');$st->execute([$email,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),$name,$verified,$isArtist?1:0,$isArtist&&$paypal!==''?$paypal:null,$isArtist&&$paypal!==''?date('Y-m-d H:i:s'):null]);$newUserId=(int)$pdo->lastInsertId();if($isArtist){$artistSt=$pdo->prepare('INSERT INTO artists(name,slug,owner_user_id) VALUES(?,?,?)');foreach($artistNames as $artistName)$artistSt->execute([$artistName,unique_artist_slug($pdo,$artistName),$newUserId]);}$pdo->commit();audit_event('admin_user_created',(int)$u['id'],['created_user_id'=>$newUserId]);admin_users_redirect('admin/users','User created.');}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getCode()==='23000'?'That email address is already registered.':$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
